OM_uint32 process_spnego_continuation(OM_uint32 *minstat, gss_buffer_t buf,
                                      gss_ctx_id_t *ctx,
                                      gss_buffer_t *responseToken,
                                      gss_buffer_t *mechListMIC,
                                      OM_uint33 *negState,
                                      send_token_flag *return_token) {
    OM_uint32 status = 0;
    OM_uint32 major_status, minor_status;
    gss_OID mech_type = GSS_C_NULL_OID;
    gss_buffer_desc output_token = GSS_C_EMPTY_BUFFER;

    /* Verify the token header */
    if (buf->length < 4 || memcmp(buf->value, "NEGO", 4) != 0) {
        *minstat = GSS_S_BAD_SIG;
        return GSS_S_FAILURE;
    }

    /* Check for a valid context */
    if (*ctx == GSS_C_NO_CONTEXT) {
        *minstat = GSS_S_NO_CONTEXT;
        return GSS_S_FAILURE;
    }

    /* Process the negotiation response */
    major_status = gss_unwrap(&minor_status, *ctx, buf, &output_token, NULL, NULL, NULL);
    if (major_status != GSS_S_COMPLETE) {
        *minstat = minor_status;
        return major_status;
    }

    /* Update the negotiation state */
    *negState = NEGOTIATION_COMPLETE;

    /* Store the response token */
    if (responseToken != NULL) {
        responseToken->length = output_token.length;
        responseToken->value = output_token.value;
    }

    /* Store mechanism list MIC if needed */
    if (mechListMIC != NULL) {
        mechListMIC->length = 0;
        mechListMIC->value = NULL;
    }

    *return_token = SEND_TOKEN;

    return GSS_S_COMPLETE;
}

OM_uint32 process_spnego_continuation(OM_uint32 *minstat,
                                      gss_buffer_t buf,
                                      gss_ctx_id_t *ctx,
                                      gss_buffer_t *responseToken,
                                      gss_buffer_t *mechListMIC,
                                      OM_uint32 *negState,
                                      send_token_flag *return_token) {
    OM_uint32 status = 0;

    /* Verify the token header */
    if (!buf || buf->length < 1) {
        *minstat = GSS_S_BAD_TOKEN;
        return GSS_S_FAILURE;
    }

    /* Check for valid context */
    if (!ctx || *ctx == GSS_C_NO_CONTEXT) {
        *minstat = GSS_S_NO_CONTEXT;
        return GSS_S_FAILURE;
    }

    /* Process the negotiation response */
    status = gss_process_token(ctx, buf, responseToken);

    if (status != GSS_S_COMPLETE && status != GSS_S_CONTINUE_NEEDED) {
        *minstat = status;
        return status;
    }

    /* Update the negotiation state */
    if (status == GSS_S_CONTINUE_NEEDED) {
        *negState = SPNEGO_CONTINUE;
    } else {
        *negState = SPNEGO_COMPLETE;
    }

    /* Manage memory for the supported mechanism */
    if (mechListMIC && mechListMIC->length > 0) {
        gss_release_buffer(minstat, mechListMIC);
    }

    /* Set token sending flag */
    if (responseToken->length > 0) {
        *return_token = SEND_TOKEN;
    } else {
        *return_token = DO_NOT_SEND_TOKEN;
    }

    return status;
}

OM_uint32 process_spnego_continuation(
    OM_uint32 *minstat,
    gss_buffer_t buf,
    gss_ctx_id_t *ctx,
    gss_buffer_t *responseToken,
    gss_buffer_t *mechListMIC,
    OM_uint33 *negState,
    send_token_flag *return_token
) {
    OM_uint32 status = GSS_S_BAD_SIG;
    OM_uint32 maj_stat, min_stat = 0;

    gss_OID mech_type;
    gss_buffer_desc token = GSS_C_EMPTY_BUFFER;
    gss_cred_id_t cred = GSS_C_NO_CREDENTIAL;

    if (buf->length < 1) {
        if (minstat)
            *minstat = GSS_S_BAD_BINDINGS;
        return GSS_S_DEFECTIVE_TOKEN;
    }

    if (ctx == NULL || negState == NULL || return_token == NULL)
        return GSS_S_FAILURE;

    maj_stat = gss_get_calling_cred(&min_stat, &cred);
    if (maj_stat != GSS_S_COMPLETE)
        return GSS_S_FAILURE;

    maj_stat = gss_import_name(&min_stat, buf, &gss_spnego_mech_oid, &ctx);
    if (maj_stat != GSS_S_COMPLETE) {
        gss_release_cred(&min_stat, &cred);
        return GSS_S_BAD_SIG;
    }

    maj_stat = gss_init_sec_context(
        &min_stat,
        cred,
        ctx,
        target_name,
        GSS_C_NULL_OID,
        GSS_C_MUTUAL_FLAG,
        0,
        NULL,
        NULL,
        NULL,
        responseToken,
        NULL,
        negState,
        return_token
    );

    if (maj_stat != GSS_S_CONTINUE_NEEDED && maj_stat != GSS_S_COMPLETE) {
        gss_delete_sec_context(&min_stat, ctx, NULL);
        gss_release_cred(&min_stat, &cred);
        return GSS_S_FAILURE;
    }

    if (responseToken && mechListMIC) {
        token.length = 0;
        token.value = NULL;
        maj_stat = gss_wrap(
            &min_stat,
            *ctx,
            0,
            GSS_C_QOP_DEFAULT,
            &token,
            NULL,
            mechListMIC
        );
        if (maj_stat != GSS_S_COMPLETE) {
            gss_delete_sec_context(&min_stat, ctx, NULL);
            gss_release_cred(&min_stat, &cred);
            return GSS_S_FAILURE;
        }
    }

    gss_release_cred(&min_stat, &cred);
    *minstat = min_stat;
    return maj_stat;
}

OM_uint32 process_spnego_continuation(OM_uint32 *minstat, gss_buffer_t buf, gss_ctx_id_t *ctx,
                                      gss_buffer_t *responseToken, gss_buffer_t *mechListMIC,
                                      OM_uint32 *negState, send_token_flag *return_token) {
    OM_uint32 status = 0;
    OM_uint32 minor_status = 0;
    gss_OID mech_type = GSS_C_NULL_OID;
    gss_buffer_desc token = {0, NULL};

    /* Verify the token header and process the negotiation response */
    if (buf->length < GSS_SPNEGO_HEADER_SIZE || memcmp(buf->value, GSS_SPNEGO_OID_STR, GSS_SPNEGO_HEADER_SIZE) != 0) {
        *minstat = GSS_S_BAD_TOKEN;
        return GSS_S_FAILURE;
    }

    /* Check and initialize context if valid */
    if (*ctx == NULL) {
        status = gss_init_sec_context(&minor_status, GSS_C_NO_CREDENTIAL, ctx, NULL, GSS_C_NULL_OID_SET,
                                      0, 0, NULL, NULL, &mech_type, responseToken, NULL, return_token);
        if (status != GSS_S_COMPLETE && status != GSS_S_CONTINUE_NEEDED) {
            *minstat = status;
            return GSS_S_FAILURE;
        }
    } else {
        status = gss_accept_sec_context(&minor_status, ctx, buf, NULL, GSS_C_NULL_OID_SET, 0, NULL,
                                        &token, return_token, NULL, NULL);
        if (status != GSS_S_CONTINUE_NEEDED && status != GSS_S_COMPLETE) {
            *minstat = status;
            return GSS_S_FAILURE;
        }
    }

    /* Update negotiation state accordingly */
    if (status == GSS_S_CONTINUE_NEEDED) {
        *negState = GSS_NEG_STATE_CONTINUE;
    } else if (status == GSS_S_COMPLETE) {
        *negState = GSS_NEG_STATE_COMPLETE;
    }

    /* Memory management for the supported mechanism */
    if (token.length > 0) {
        token.value = malloc(token.length);
        if (token.value == NULL) {
            *minstat = GSS_S_FAILURE;
            return GSS_S_FAILURE;
        }
        memcpy(token.value, buf->value, token.length);
        *mechListMIC = token;
    }

    return status;
}

OM_uint32 process_spnego_continuation(
    OM_uint32 *minstat,
    gss_buffer_t buf,
    gss_ctx_id_t *ctx,
    gss_buffer_t *responseToken,
    gss_buffer_t *mechListMIC,
    OM_uint32 *negState,
    send_token_flag *return_token) {

    OM_uint32 status = 0;
    gss_buffer_desc token = {0, 0};

    *minstat = 0;

    if (!buf || buf->length <= 0 || !ctx || !responseToken || !negState || !return_token) {
        status = GSS_S_BAD_ARGUMENT;
        return status;
    }

    // Verify the token header (e.g., check for proper SPNEGO OIDs)
    if (memcmp(buf->value, "NEGO", 4) != 0) {
        status = GSS_S_BAD_TOKEN;
        return status;
    }

    // Check for valid context
    if (*ctx == GSS_C_NO_CONTEXT) {
        status = GSS_S_NO_CONTEXT;
        return status;
    }

    // Process the negotiation response
    if (gss_unwrap(minstat, *ctx, buf, &token, NULL, NULL, NULL) != GSS_S_COMPLETE) {
        status = *minstat;
        return status;
    }

    // Update the negotiation state based on the response
    if (token.length > 0) {
        *negState = NEG_STATE_CONTINUE;
    } else {
        *negState = NEG_STATE_COMPLETE;
    }

    // Store the response token
    responseToken->length = token.length;
    responseToken->value = token.value;

    // Store the MIC if available
    if (mechListMIC) {
        mechListMIC->length = 0;
        mechListMIC->value = NULL;
    }

    // Determine if the token should be sent back
    if (*negState == NEG_STATE_CONTINUE) {
        *return_token = SEND_TOKEN_FLAG_SEND;
    } else {
        *return_token = SEND_TOKEN_FLAG_DONT_SEND;
    }

    return status;
}
